// ─── Extract Sold Products ────────────────────────────────────────
// Parses the Medusa order response to get product IDs and metadata
// for cross-platform inventory sync.

const orderData = $input.first().json;
const order = orderData.order || orderData;

const items = (order.items || []).map(item => ({
  product_id: item.product_id,
  variant_id: item.variant_id,
  title: item.title,
  quantity: item.quantity,
  unit_price: item.unit_price,
  metadata: item.metadata || {},
}));

const result = {
  order_id: order.id,
  order_status: order.status,
  customer_email: order.email,
  total: order.total,
  currency: order.currency_code,
  items: items,
  product_ids: items.map(i => i.product_id),
  created_at: order.created_at,
};

console.log(`[InvStorage] Order ${result.order_id}: ${items.length} item(s) sold`);
items.forEach(item => {
  console.log(`  - ${item.title} (product: ${item.product_id}, qty: ${item.quantity})`);
});

return [{ json: result }];

// ─── Generate Inventory Update Requests ───────────────────────────
// Creates one output item per sold product, each containing the API
// call needed to set Medusa inventory to 0 (mark as sold/out of stock).

const order = $input.first().json;
const updates = [];

for (const item of (order.items || [])) {
  updates.push({
    json: {
      order_id: order.order_id,
      product_id: item.product_id,
      variant_id: item.variant_id,
      title: item.title,
      action: 'mark_sold',
      // The next HTTP node will use these to update Medusa
      update_url: `http://medusa:9000/admin/products/${item.product_id}`,
      update_body: { status: 'draft', metadata: { sold: true, sold_order_id: order.order_id, sold_at: new Date().toISOString() } },
    }
  });
}

console.log(`[InvStorage] Prepared ${updates.length} inventory update(s)`);
return updates;

// ─── Parse eBay Sold Notification ─────────────────────────────────
// Extracts the eBay Item ID from the IPN and looks up the
// corresponding Medusa product.

const notification = $input.first().json;

// eBay IPN fields vary by notification type
const ebayItemId = notification.ItemID || notification.item_id || notification.itemId;
const salePrice = notification.SalePrice || notification.sale_price;

console.log(`[InvStorage] eBay item sold: ${ebayItemId}`);

return [{
  json: {
    ebay_item_id: ebayItemId,
    sale_price: salePrice,
    source: 'ebay',
    // Next step: query Medusa for the product with this eBay ID in metadata
    medusa_search_url: `http://medusa:9000/admin/products?metadata[ebay_item_id]=${ebayItemId}`
  }
}];
